const { test } = require('node:test');
const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const path = require('node:path');
const http = require('node:http');

const SERVER_SCRIPT = path.join(__dirname, '..', 'server.js');
const TARGET_URL = 'http://127.0.0.1:3000/api/hello';
const EXPECTED_BODY = '{"message":"hello"}';
const STARTUP_TIMEOUT_MS = 5000;
const POLL_INTERVAL_MS = 100;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function requestOnce(url) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode,
          body: Buffer.concat(chunks).toString('utf8'),
        });
      });
    });
    req.on('error', reject);
  });
}

async function waitForServer(url, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  let lastError = null;
  while (Date.now() < deadline) {
    try {
      return await requestOnce(url);
    } catch (err) {
      lastError = err;
      await sleep(POLL_INTERVAL_MS);
    }
  }
  throw new Error(
    `server not reachable at ${url} within ${timeoutMs}ms: ${lastError ? lastError.message : 'unknown error'}`
  );
}

test('GET /api/hello returns 200 with exact body {"message":"hello"}', async (t) => {
  const child = spawn(process.execPath, [SERVER_SCRIPT], { stdio: 'ignore' });

  let spawnError = null;
  child.on('error', (err) => {
    spawnError = err;
  });

  t.after(async () => {
    child.kill('SIGTERM');
    await new Promise((resolve) => {
      if (child.exitCode !== null || child.signalCode !== null) {
        resolve();
        return;
      }
      child.once('exit', resolve);
    });
  });

  const response = await waitForServer(TARGET_URL, STARTUP_TIMEOUT_MS);
  assert.ok(spawnError === null, `server.js failed to start: ${spawnError ? spawnError.message : ''}`);
  assert.equal(response.status, 200);
  assert.equal(response.body, EXPECTED_BODY);
});
